GELIJK = {'juultjeverhuur@gmail.com', 'Juultje Zeeland', 'NL', 'DE', 'EN', 'Wissenkerke, Noord-Beveland', '+7', '+3', '9,1', '4,92', '4,84', 'Airbnb',
          'Instagram:', '@juultjezeeland', 'Nederlands', 'Deutsch', 'English', '©', '2026', '">', '.', 'Wissenkerke, Zeeland',
          'www.autoriteitpersoonsgegevens.nl',
          'Kamperland', 'Kortgene', 'Colijnsplaat', 'Neeltje Jans', 'Goes', 'Veere', 'Zierikzee', 'Middelburg', 'Domburg', 'Vlissingen'}

def vertaal(tekst, tabel, regels, missers):
    kern = tekst.strip()
    if not kern:
        return tekst
    if kern in tabel:
        nieuw = tabel[kern]
    else:
        for pat, rep in regels:
            if re.match(pat, kern):
                nieuw = re.sub(pat, rep, kern); break
        else:
            if kern not in GELIJK:
                missers.append(kern)
            return tekst
    i = tekst.index(kern)
    return tekst[:i] + nieuw + tekst[i + len(kern):]

def maak(bron, taal, tabel, regels, bestand):
    missers = []
    delen = re.split(r'(<[^>]+>)', bron)
    uit, in_code = [], False
    for d in delen:
        if d.startswith('<'):
            tag = d.lower()
            if tag.startswith(('<style', '<script')): in_code = True
            elif tag.startswith(('</style', '</script')): in_code = False
            def attr(m):
                return f'{m.group(1)}="{vertaal(m.group(2), tabel, regels, missers)}"'
            d = re.sub(r'\b(alt|aria-label|data-teller|data-titel)="([^"]*)"', attr, d)
            if d.startswith('<meta name="description"'):
                d = re.sub(r'content="([^"]*)"', lambda m: f'content="{vertaal(m.group(1), tabel, regels, missers)}"', d)
            uit.append(d)
        else:
            uit.append(d if in_code else vertaal(d, tabel, regels, missers))
    h = ''.join(uit)
    h = h.replace('<html lang="nl">', f'<html lang="{taal}">')
    h = h.replace('login.smoobu.com/nl/booking-tool', f'login.smoobu.com/{taal}/booking-tool')
    # taalkeuze in het menu: NL wordt een link, de eigen taal wordt vet
    nl_pagina = './' if bestand == 'index.html' else bestand
    def talen(m):
        li = m.group(0).replace('<strong>NL</strong>', f'<a href="{nl_pagina}" lang="nl" hreflang="nl">NL</a>')
        return re.sub(rf'<a href="[^"]*" lang="{taal}" hreflang="{taal}">{taal.upper()}</a>', f'<strong>{taal.upper()}</strong>', li)
    h, n = re.subn(r'<li class="talen">.*?</li>', talen, h)
    assert n == 1, (bestand, taal, 'taalkeuze niet gevonden')
    # links en bestanden: de taalversies staan een map dieper
    def url(u, nl_link):
        if u.startswith(('http', '//', 'data:', 'tel:', 'mailto:', '#')):
            return u
        if u.startswith(taal + '/'):
            return u[len(taal) + 1:] or './'
        if u.startswith(('de/', 'en/', 'assets/')):
            return '../' + u
        if nl_link:
            return '../' + ('' if u == './' else u)
        return u
    def tag(m):
        t = m.group(0)
        nl_link = 'hreflang="nl"' in t and not t.startswith('<link')
        t = re.sub(r'\b(href|src)="([^"]*)"', lambda a: f'{a.group(1)}="{url(a.group(2), nl_link)}"', t)
        t = re.sub(r'\b(imagesrcset|srcset)="([^"]*)"', lambda a: a.group(1) + '="' + ', '.join(
            ' '.join([url(d.strip().split(' ')[0], False)] + d.strip().split(' ')[1:]) for d in a.group(2).split(',')) + '"', t)
        return t
    h = re.sub(r'<(?:a|link|img|source|script)\b[^>]*>', tag, h)
    return h, missers


